using Microsoft.Data.SqlClient;
namespace WhatsBiz.Api.Middleware; public sealed class AuditMiddleware(RequestDelegate next, IConfiguration configuration) { public async Task InvokeAsync(HttpContext context) { await next(context); var method = context.Request.Method; var path = context.Request.Path.Value ?? ""; if (method is not ("POST" or "PUT" or "PATCH" or "DELETE") && !path.Contains("/print", StringComparison.OrdinalIgnoreCase) && !path.Contains("/export", StringComparison.OrdinalIgnoreCase)) return; try { await using var c = new SqlConnection(configuration.GetConnectionString("DefaultConnection")); await c.OpenAsync(context.RequestAborted); await using var q = new SqlCommand("INSERT admin.AuditLogs(UserName,Action,EntityType,RequestPath,HttpMethod,IpAddress,Succeeded) VALUES(@user,@action,@entity,@path,@method,@ip,@ok)", c); var action = path.Contains("print", StringComparison.OrdinalIgnoreCase) ? "PRINT" : path.Contains("export", StringComparison.OrdinalIgnoreCase) ? "EXPORT" : method switch { "POST" => "CREATE", "PUT" or "PATCH" => "UPDATE", "DELETE" => "DELETE", _ => method }; q.Parameters.AddWithValue("@user", (object?)context.User.Identity?.Name ?? DBNull.Value); q.Parameters.AddWithValue("@action", action); q.Parameters.AddWithValue("@entity", path.Split('/', StringSplitOptions.RemoveEmptyEntries).LastOrDefault() ?? ""); q.Parameters.AddWithValue("@path", path); q.Parameters.AddWithValue("@method", method); q.Parameters.AddWithValue("@ip", (object?)context.Connection.RemoteIpAddress?.ToString() ?? DBNull.Value); q.Parameters.AddWithValue("@ok", context.Response.StatusCode < 400); await q.ExecuteNonQueryAsync(context.RequestAborted); } catch { } } }
